 public static class ProductTests {
  static void Pump(Task task){var frame=new DispatcherFrame();var until=DateTime.UtcNow.AddSeconds(15);var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(15)};timer.Tick+=(s,e)=>{if(task.IsCompleted||DateTime.UtcNow>until){timer.Stop();frame.Continue=false;}};timer.Start();Dispatcher.PushFrame(frame);if(!task.IsCompleted)throw new TimeoutException("Ürün testi zaman aşımı.");task.GetAwaiter().GetResult();}
  static Binding Macro(string app){return new Binding{Name="Mouse macro",Key=5,Mods=2,IsMacro=true,Kind="Workflow",Steps=new List<ActionStep>{new ActionStep{Kind="Mouse drag",AppPath=app,MouseButton=3,X=20,Y=20,X2=80,Y2=70,WindowWidth=400,WindowHeight=300,Duration=500,ScaleWithWindow=true},new ActionStep{Kind="Scroll",AppPath=app,X=20,Y=20,WindowWidth=400,WindowHeight=300,ScrollDelta=-240,Horizontal=true}}};}
  public static void Unit(Action<bool,string> check){
   foreach(int key in InputKeys.Pointers){TriggerSpec gesture;check(TriggerSpec.TryParse("Ctrl+"+InputKeys.Token(key),out gesture)&&gesture.Key==key&&gesture.Mods==2&&TriggerSpec.Mentioned("When I press "+gesture.Text+", copy",gesture),"Mouse tetikleyicisi prompt / tuş alanında tanınır: "+InputKeys.Token(key));check(Rules.Reserved(2,key)==null&&Rules.Sendable(2,key)==null,"Mouse tetikleyicisi ve gönderme geçerli: "+InputKeys.Token(key));}
   check(Native.PointerDown(3)==128&&Native.PointerUp(3)==256&&Native.PointerData(3)==1&&Native.PointerData(4)==2,"X1 ve X2 yerel Windows mouse verisi doğru kodlanır");check(SystemShortcuts.ValidateLink(2,5)!=null,"Windows .lnk için mouse tuşu kaydı reddedilir");
   string root=Path.Combine(Path.GetTempPath(),"MakroPlus-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
    string app=System.Reflection.Assembly.GetExecutingAssembly().Location;var macro=Macro(app);check(Rules.Validate(macro,new Binding[0])==null,"Yan tuşlu sürükleme ve yatay kaydırma doğrulanır");var invalid=macro.Copy();invalid.Steps[0].X=double.NaN;check(Rules.Validate(invalid,new Binding[0])!=null,"NaN mouse konumu reddedilir");invalid.Steps[0].X=double.PositiveInfinity;check(Rules.Validate(invalid,new Binding[0])!=null,"Sonsuz mouse konumu reddedilir");invalid=macro.Copy();invalid.Steps[0].Duration=30001;check(Rules.Validate(invalid,new Binding[0])!=null,"Aşırı mouse basılı tutma reddedilir");invalid=macro.Copy();invalid.Steps[1].ScrollDelta=0;check(Rules.Validate(invalid,new Binding[0])!=null,"Sıfır kaydırma kaydı reddedilir");
    string duplicateApp=Path.Combine(root,Path.GetFileName(app));File.WriteAllText(duplicateApp,"");var explicitRequest=new LlmRequest{Prompt="Open example:content in the selected app when I press F9.",Trigger="F9",TargetApp=app,Applications=new List<string>{app,duplicateApp}};string selectedId=LlmProtocol.AppMap(explicitRequest).Single(p=>p.Value==app).Key;string reply=LocalLlm.Json().Serialize(new{status="ready",name="Explicit target",trigger="F9",app_id=selectedId,message="",notes=new string[0],steps=new[]{new{kind="open_resource",combo="",text="example:content",ms=0}}});check(LlmProtocol.ReadPlan(reply,explicitRequest).Ready,"Aynı exe adından iki tane olsa da elle seçilen tam hedef kabul edilir");
    var state=new State{UseGpu=false};state.Bindings.Add(macro);state.History.Add(new Activity{Name="test",Result="test",Time="test"});string file=Path.Combine(root,"settings.json");Transfer.Export(state,file);var imported=Storage.Read(file);check(imported.History.Count==0&&imported.Bindings.Single().Steps[0].Duration==500&&imported.Bindings.Single().Steps[1].Horizontal&&imported.UseGpu==false,"Tüm mouse alanları ve GPU tercihi aktarılır; geçmiş aktarılmaz");
    var incoming=Transfer.Clone(imported);string old=Path.Combine(root,"old","app.exe");incoming.Bindings[0].Steps.ForEach(s=>s.AppPath=old);incoming.ApplicationPaths.Add(old);var result=Transfer.Import(new State(),incoming,new Dictionary<string,string>{{old,app}},true);check(result.Added==1&&result.Disabled==0&&result.State.UseGpu==false&&result.State.Bindings[0].Steps.All(s=>s.AppPath==app)&&incoming.Bindings[0].Steps[0].AppPath==old,"Başka cihazdaki uygulama yolu asıl veriyi değiştirmeden eşleştirilir");
    result=Transfer.Import(new State(),incoming,new Dictionary<string,string>(),true);check(result.Disabled==1&&result.Issues.Count==1&&!result.State.Bindings[0].Enabled,"Eksik hedefle gelen atama kaybolmadan pasif tutulur");result=Transfer.Import(state,imported,new Dictionary<string,string>(),true);check(result.Disabled==1&&result.State.Bindings.Select(b=>b.Id).Distinct().Count()==2,"Yinelenen içe aktarma çakışmayı etkinleştirmez");
    state.Bindings[0].Name="before";Storage.Write(state,file);state.Bindings[0].Name="after";Storage.Write(state,file);File.WriteAllText(file,"broken json");string notice;var recovered=Storage.LoadRecoverable(file,out notice);check(recovered.Bindings.Single().Name=="before"&&recovered.Paused&&notice.Length>0&&Directory.GetFiles(root,"*.corrupt-*.json").Length==1,"Bozuk ayarlar korunur ve yedek duraklatılarak kurtarılır");
    File.WriteAllText(Path.Combine(root,"orphan.json"),"broken");recovered=Storage.LoadRecoverable(Path.Combine(root,"orphan.json"),out notice);check(recovered.Bindings.Count==0&&recovered.Paused&&notice.Contains("empty"),"Yedeği olmayan bozuk dosya korunur ve güvenli boş oturum açılır");
    Parallel.For(0,20,i=>{var copy=Transfer.Clone(state);copy.Bindings[0].Name="writer-"+i;Storage.Write(copy,file);});check(Storage.Read(file).Bindings[0].Name.StartsWith("writer-")&&Directory.GetFiles(root,"*.tmp").Length==0,"Eşzamanlı kayıtlar tam JSON bırakır ve geçici dosya sızdırmaz");
    var bytes=File.ReadAllBytes(file);File.SetAttributes(file,FileAttributes.ReadOnly);bool refused=false;try{Storage.Write(state,file);}catch(IOException){refused=true;}catch(UnauthorizedAccessException){refused=true;}finally{File.SetAttributes(file,FileAttributes.Normal);}check(refused&&File.ReadAllBytes(file).SequenceEqual(bytes)&&Directory.GetFiles(root,"*.tmp").Length==0,"Yazılamayan ayar dosyası ve geçici dosyalar korunur");
    File.WriteAllText(file,"{\"Bindings\":[{\"Id\":\"a\",\"Name\":\"x\",\"AppPath\":\"\",\"Target\":\"\",\"Kind\":\"İşlem dizisi\",\"Steps\":[null]}],\"History\":[]}");bool rejected=false;try{Storage.Read(file);}catch(InvalidDataException){rejected=true;}check(rejected,"Bozuk null makro adımı yüklemede yakalanır");
    var modelRoot=Path.Combine(root,"relocated");Directory.CreateDirectory(Path.Combine(modelRoot,"models"));string bundled=Path.Combine(modelRoot,"models","user-selected.gguf");File.WriteAllText(bundled,"GGUF");check(ModelFiles.Resolve("",modelRoot,root)==bundled,"A single user-supplied GGUF in the models folder is discovered without a fixed filename");
   }finally{foreach(var path in Directory.GetFiles(root,"*",SearchOption.AllDirectories))File.SetAttributes(path,FileAttributes.Normal);if(!Path.GetFullPath(root).StartsWith(Path.GetFullPath(Path.GetTempPath())+"MakroPlus-",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Geçici test klasörü doğrulanamadı.");Directory.Delete(root,true);}
  }
  public static void Ui(MainWindow owner,KeyboardEngine keyboard,Action<bool,string> check,Action<Window,string> screenshot,Action<string> skip){
   check(Brand.Cover.PixelWidth>0&&Brand.Cover.PixelHeight>0,"Kullanıcının kapak görseli exe içine gömülüdür");owner.ProductViewForTest("Home");screenshot(owner,"makroplus-cover-preview.png");Theme.Apply(false);screenshot(owner,"makroplus-cover-light-preview.png");Theme.Apply(true);owner.ProductViewForTest("Transfer and diagnostics");screenshot(owner,"makroplus-device-preview.png");owner.ProductViewForTest("Mouse shortcuts");screenshot(owner,"makroplus-mouse-preview.png");check(true,"Kapak, mouse ve cihaz ekranları açılır");
   string app=System.Reflection.Assembly.GetExecutingAssembly().Location;var step=Macro(app).Steps[0];var editor=new StepEditor(step){Owner=owner};editor.Show();try{editor.FieldForTest("X","35.5");editor.FieldForTest("Duration","1250");editor.FieldForTest("Mods","Ctrl+Alt");var edited=editor.DraftForTest();check(edited.MouseButton==3&&edited.X==35.5&&edited.Duration==1250&&edited.Mods==3&&edited.ScaleWithWindow,"Mouse kayıt ayrıntıları gerçek düzenleyicide değiştirilir");editor.FieldForTest("X","NaN");bool rejected=false;try{editor.DraftForTest();}catch(ArgumentException){rejected=true;}check(rejected,"Düzenleyici geçersiz sayıları kaydetmez");editor.FieldForTest("X","35.5");screenshot(editor,"makroplus-step-preview.png");}finally{editor.Close();}
   using(var engine=new KeyboardEngine()){engine.AllowOwnPointerForTest=true;var binding=new Binding{Name="X1 test",Key=5,Mods=2};engine.Bindings=()=>new List<Binding>{binding};int fires=0;engine.Fire=(b,w)=>fires++;check(engine.IdleForTest,"Boştaki klavye / mouse motoru zamanlayıcı çalıştırmaz");engine.Handle(new Native.Keyboard{vk=162});bool down=engine.MouseForTest(0x20B,new Native.MouseEvent{Data=1u<<16});bool up=engine.MouseForTest(0x20C,new Native.MouseEvent{Data=1u<<16});engine.FlushForTest();check(down&&up&&fires==0,"Ctrl basılıyken mouse eylemi bekler ve olayları engeller");engine.Handle(new Native.Keyboard{vk=162,flags=128});engine.FlushForTest();check(fires==1&&engine.IdleForTest,"Ctrl+X1 bir kez çalışır ve motor tekrar boşta kalır");engine.MouseForTest(0x20B,new Native.MouseEvent{Data=1u<<16,Flags=1});engine.MouseForTest(0x20C,new Native.MouseEvent{Data=1u<<16,Flags=1});engine.FlushForTest();check(fires==1,"Sentetik mouse girdisi atamayı tekrar tetiklemez");
    binding.Mods=0;binding.Key=InputKeys.WheelLeft;engine.MouseForTest(0x20E,new Native.MouseEvent{Data=unchecked((uint)(-120<<16))});engine.FlushForTest();check(fires==2,"Yatay tekerlek doğru yönde bir kez tetiklenir");binding.Key=5;binding.PassThrough=true;check(!engine.MouseForTest(0x20B,new Native.MouseEvent{Data=1u<<16}),"Mouse kaynak uygulamaya iletim seçeneğine uyar");engine.MouseForTest(0x20C,new Native.MouseEvent{Data=1u<<16});engine.FlushForTest();check(fires==3,"İletilen mouse olayı yine tek atama çalıştırır");
    int capture=0;engine.Paused=true;engine.Capture=(m,k,p,a)=>capture=k;engine.MouseForTest(0x20B,new Native.MouseEvent{Data=2u<<16});engine.MouseForTest(0x20C,new Native.MouseEvent{Data=2u<<16});Application.Current.Dispatcher.Invoke(DispatcherPriority.ApplicationIdle,new Action(()=>{}));check(capture==6,"Kayıt alanı X2 yan tuşunu yakalar");engine.Capture=null;
   }
   using(var engine=new KeyboardEngine()){var bindings=Enumerable.Range(0,1000).Select(i=>new Binding{Name="load-"+i,Key=119,AppPath=@"C:\test\"+i+".exe"}).ToList();bindings.Add(new Binding{Name="hit",Key=119});engine.Bindings=()=>bindings;int hits=0;engine.Fire=(b,w)=>hits++;var watch=Stopwatch.StartNew();for(int i=0;i<2000;i++){engine.Handle(new Native.Keyboard{vk=119});engine.Handle(new Native.Keyboard{vk=119,flags=128});engine.FlushForTest();}watch.Stop();check(hits==2000&&engine.IdleForTest,"1001 atama / 4000 olay stresinde tetik kaybı veya boşta zamanlayıcı yok");File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"performance-test.json"),LocalLlm.Json().Serialize(new{bindings=bindings.Count,events=4000,fires=hits,milliseconds=watch.ElapsedMilliseconds,idle_timer=engine.IdleForTest,os=Environment.OSVersion.ToString()}));}
   MouseRecorder(owner,keyboard,check,skip);
  }
  static void MouseRecorder(Window owner,KeyboardEngine keyboard,Action<bool,string> check,Action<string> skip){
   var window=new Window{Title="Makro+ mouse fixture",Width=480,Height=320,Owner=owner,Topmost=true,WindowStartupLocation=WindowStartupLocation.CenterScreen};window.Content=new TextBlock{Text="Controlled mouse target"};window.Show();IntPtr handle=new WindowInteropHelper(window).Handle;
   try{var rect=AutomationElement.FromHandle(handle).Current.BoundingRectangle;using(var recorder=new MacroRecorder(keyboard)){recorder.AllowOwnProcess=true;recorder.Start(false);var input=new Native.MouseEvent{Point=new Native.Point{X=(int)rect.Left+40,Y=(int)rect.Top+100},Data=1u<<16};recorder.MouseForTest(0x20B,input,handle,0,0);recorder.MouseForTest(0x20C,input,handle,0,650);input.Data=unchecked((uint)(-120<<16));recorder.MouseForTest(0x20E,input,handle,0,850);var stop=recorder.StopAsync();Pump(stop);var steps=stop.Result;check(steps.Any(s=>s.Kind=="Mouse click"&&s.MouseButton==3&&s.Duration==650)&&steps.Any(s=>s.Kind=="Scroll"&&s.Horizontal&&s.ScrollDelta==-120),"X1 basılı tutma ve yatay kaydırma gerçek kayıt kuyruğunda görünür");check(steps.Where(s=>s.Kind=="Wait").Sum(s=>s.Delay)==200,"Basılı tutma süresi bekleme olarak ikinci kez eklenmez");}
    var cancelled=new CancellationTokenSource();cancelled.Cancel();bool stopped=false;try{Pump(Actions.RunSteps(Macro(System.Reflection.Assembly.GetExecutingAssembly().Location),handle,cancelled.Token));}catch(OperationCanceledException){stopped=true;}check(stopped,"İptal edilmiş mouse makrosu giriş göndermeden durur");
    Native.ActivateWindow(handle);if(Native.GetForegroundWindow()!=handle){skip("Mouse yan tuş oynatma: test penceresine ön plan izni verilmedi.");return;}int xDown=0,xUp=0;var source=HwndSource.FromHwnd(handle);source.AddHook((IntPtr h,int msg,IntPtr w,IntPtr l,ref bool handled)=>{if(msg==0x20B)xDown++;if(msg==0x20C)xUp++;return IntPtr.Zero;});var step=new ActionStep{Kind="Mouse click",MouseButton=3,X=40,Y=100,WindowWidth=rect.Width,WindowHeight=rect.Height,Duration=30,ScaleWithWindow=true};window.Width=600;window.UpdateLayout();Pump(Actions.RunSteps(new Binding{IsMacro=true,Steps=new List<ActionStep>{step}},handle));Pump(Task.Delay(100));check(xDown==1&&xUp==1,"Orantılı boyut değişiminde gerçek X1 basma ve bırakma hedefe ulaşır");
    var cancel=new CancellationTokenSource();cancel.CancelAfter(80);step.Duration=1000;step.Mods=2;bool cancelledHold=false;try{Pump(Actions.RunSteps(new Binding{IsMacro=true,Steps=new List<ActionStep>{step}},handle,cancel.Token));}catch(OperationCanceledException){cancelledHold=true;}Pump(Task.Delay(100));check(cancelledHold&&xDown==2&&xUp==2&&(Native.GetAsyncKeyState(162)&0x8000)==0,"İptalde basılı mouse düğmesi ve Ctrl mutlaka bırakılır");
   }finally{window.Close();}
  }
  public static int Real(){var results=new List<object>();string report=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"device-model-test.json");using(var model=new LocalLlm())try{
   var state=Storage.Read(Storage.FilePath);var request=new LlmRequest{Prompt="When I press XButton1, select all text and copy it.",SelectedApp="",Trigger="",Applications=new List<string>(),ModelPath=state.ModelPath,Gpu=true};model.SimulateGpuFailureForTest=true;var watch=Stopwatch.StartNew();var plan=model.AnalyzeAsync(request,p=>{},CancellationToken.None).GetAwaiter().GetResult();bool valid=plan.Ready&&plan.Binding.Key==5&&plan.Binding.Steps.Count==2&&plan.Binding.Steps[0].Key==65&&plan.Binding.Steps[1].Key==67&&model.BackendForTest=="CPU"&&model.FallbackCount==1;results.Add(new{scenario="GPU unavailable → actual CPU inference",passed=valid,milliseconds=watch.ElapsedMilliseconds,binding=plan.Binding,backend=model.BackendForTest});if(!valid)throw new Exception("CPU fallback / mouse model plan mismatch.");
   request.Prompt="Assign Ctrl+WheelUp to type \"Makro+\".";plan=model.AnalyzeAsync(request,p=>{},CancellationToken.None).GetAwaiter().GetResult();valid=plan.Ready&&plan.Binding.Key==InputKeys.WheelUp&&plan.Binding.Mods==2&&plan.Binding.Steps.Count(s=>s.Kind=="Text")==1&&plan.Binding.Steps.Single(s=>s.Kind=="Text").Text=="Makro+"&&plan.Binding.Steps.All(s=>s.Kind=="Text"||s.Kind=="Wait")&&model.StartupCount==1&&model.FallbackCount==1;results.Add(new{scenario="CPU reuse / mouse wheel prompt",passed=valid,binding=plan.Binding,startups=model.StartupCount});if(!valid)throw new Exception("CPU reuse / wheel mismatch.");File.WriteAllText(report,LocalLlm.Json().Serialize(new{status="PASS",results=results}));return 0;
   }catch(Exception e){File.WriteAllText(report,LocalLlm.Json().Serialize(new{status="FAIL",error=e.ToString(),results=results,response=model.LastResponse,diagnostics=model.LastDiagnostics}));return 1;}
  }
 }
